using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
sealed class MultiChoiceDialog:Form {
 readonly List<CatalogItem> source;readonly HashSet<string> selected;readonly CheckedListBox list=new CheckedListBox();readonly TextBox search=Theme.Input();readonly Label status=Theme.Label("",9);readonly int maximum;bool rebuilding;public List<string> Choice;
 public MultiChoiceDialog(string title,IEnumerable<CatalogItem> values,IEnumerable<string> prior,int max=50){Text=title;source=values.ToList();selected=new HashSet<string>(prior);maximum=max;BackColor=Theme.Bg;ForeColor=Theme.Text;Font=new Font("Segoe UI",10);ClientSize=new Size(850,650);MinimumSize=Size;StartPosition=FormStartPosition.CenterParent;search.SetBounds(20,20,810,30);list.SetBounds(20,65,810,475);list.BackColor=Theme.Panel;list.ForeColor=Theme.Text;list.BorderStyle=BorderStyle.None;list.CheckOnClick=true;list.IntegralHeight=false;status.SetBounds(20,550,810,30);var clear=Theme.Button(Lang.T("Снять отметки"),delegate{selected.Clear();Filter();});clear.SetBounds(20,590,250,40);var done=Theme.Button(Lang.T("Использовать выбранные"),delegate{Choice=selected.OrderBy(x=>x).ToList();DialogResult=DialogResult.OK;Close();},true);done.SetBounds(500,590,330,40);Controls.AddRange(new Control[]{search,list,status,clear,done});search.TextChanged+=delegate{Filter();};list.ItemCheck+=delegate(object sender,ItemCheckEventArgs e){if(rebuilding)return;var item=(CatalogItem)list.Items[e.Index];if(e.NewValue==CheckState.Checked){if(selected.Count>=maximum && !selected.Contains(item.id)){e.NewValue=CheckState.Unchecked;status.Text=Lang.T("Максимум: ")+maximum;return;}selected.Add(item.id);}else selected.Remove(item.id);Count();};Filter();}
 void Count(){status.Text=Lang.T("Выбрано: ")+selected.Count+" / "+maximum+Lang.T(" · поиск сохраняет отметки");}
 void Filter(){rebuilding=true;try{list.BeginUpdate();list.Items.Clear();foreach(var item in source.Where(x=>(x.id+" "+x.name).IndexOf(search.Text.Trim(),StringComparison.OrdinalIgnoreCase)>=0).Take(1500))list.Items.Add(item,selected.Contains(item.id));list.EndUpdate();Count();}finally{rebuilding=false;}}
}
